    let s = noise(x*0.01, y*0.01)*2;
    bg.fill("#886F6F07");
    bg.rect(x, y, s, s);
  } 

	noLoop();
}

function draw() {
	scale(1, -1);  //set scale(1, -1) before saving image or thumb. Then set scale(1, 1);
  background("#EEEEEE");
	push();
	rotateX(-0.5);
	translate(0,height*0.2,0);
