			let size = noisedTube(hei,radius,dx,dy,String(x));
			//setCol(Cols[int(random(Cols.length))]);
			setCol(color(random(255), random(150,255), random(150,255)));
			push();
			translate(x+size,-hei,z);
			this._renderer.drawBuffers(String(x));
			pop();
			x += size*2+width*0.01;
			prevSize = size;
		}
	}
	pop();

	image(bg,-width/2,-height/2);
