function noisedTube(hei,radius,dx,dy,gid)
{
	const noiseScale = 0.008;
	const noiseOffset = random(100);
	if (!this._renderer.geometryInHash(gid)){
		let geom = new p5.Geometry(dx,dy);
		let maxRad = 0;
		for(let yi = 0; yi <= dy; yi ++)
		{
			var y = map(yi,0,dy,hei,0);
			for(let xi = 0; xi <= dx; xi ++)
			{
				let r = map(xi,0,dx,0,TAU);
				let nv = noise(y*noiseScale+noiseOffset);
				if(nv * radius > maxRad)maxRad = nv * radius;
				var x = cos(r)*radius*nv;
				let z = sin(r)*radius*nv;
				geom.vertices[xi + (dx+1)*yi] = createVector(x,y,z);
				geom.uvs[xi + (dx+1)*yi] = [xi/10,yi/10];
			}
		}	
		geom.computeFaces().computeNormals().averageNormals();
		geom._makeTriangleEdges()._edgesToVertices();//make stroke vert
		this._renderer.createBuffers(gid, geom);
		return maxRad;
	}
	return false;
}


//_col  color or number
function setCol(_col,_shader = sh,_uniformName = "u_col")
{
	const col = typeof (_col) == "string" ? color(_col) : _col;
	let　colArray = col._array;
	colArray.pop();
	_shader.setUniform(_uniformName,colArray);
}

function createCols(_url)
{
  let slash_index = _url.lastIndexOf('/');
  let pallate_str = _url.slice(slash_index + 1);
  let arr = pallate_str.split('-');
  for (let i = 0; i < arr.length; i++) {
    arr[i] = '#' + arr[i];
  }
  return arr;
}

let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save('pix.jpg');
    lapse = millis();
  }
}


