var vert = `
		precision highp float;

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;
		uniform float u_time;


    void main() {
      vec3 pos = aPosition;
			vec4 posOut = uProjectionMatrix * uModelViewMatrix * vec4(pos, 1.0);
      gl_Position = posOut;

      // set out value
      var_vertPos      = pos;
      var_vertNormal   =  aNormal;
      var_vertTexCoord = aTexCoord;
    }
`;


var frag = `

precision highp float;
#define PI 3.14159265358979323846

//in
uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;
uniform float u_pixelDensity;
uniform vec3 u_lightDir;
uniform sampler2D u_tex;
uniform vec3 u_col;
uniform mat3 uNormalMatrix;
uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

//attributes, in
varying vec3 var_vertPos;
varying vec4 var_centerGlPosition;
varying vec3 var_vertNormal;
varying vec2 var_vertTexCoord;

// Simple 2d noise fbm with 3 octaves
float noise2d(vec2 p)
{
    float t = texture2D(u_tex, p).x;
    t += 0.5 * texture2D(u_tex, p * 2.0).x;
    t += 0.25 * texture2D(u_tex, p * 4.0).x;
    return t / 1.75;
}


float DistanceCircle(vec2 pos, vec2 center, float radius) {
    return 1.0 - distance(pos, center) / radius;
}



float grid(vec2 uv, float weight){
	uv *= 10.;
  uv = fract(uv);
  float v =  uv.x >= 0.5-weight*0.5 && uv.x < 0.5+weight*0.5  ? 1. : 0.;
  return v;
}

void main()
{
		vec2 uv = var_vertTexCoord;
		float noise = noise2d(uv * vec2(0.5));
    vec2 pos = uv+ 0.00 * noise;// Edge roughness: 0.04

		vec3 vertNormal = normalize(uNormalMatrix * var_vertNormal);
		float dot = dot(vertNormal,-normalize(u_lightDir));
    dot = pow(dot *.6 + .5,2.) ;

		float posGrid = grid(pos,dot+0.5) * grid(vec2(pos.y,pos.x),dot+0.1);

		vec3 col = posGrid*u_col+(u_col-0.4)*(1.0-posGrid);

    gl_FragColor = vec4(vec3(col),1.0);
}

`;

